pub fn code_line_p(line: &str, lang: &str, palette: &Palette) -> Vec<Seg> {
    let style = |role: Role, mods: Modifier| palette.style(role, mods);
    let cs: Vec<char> = line.chars().collect();
    let n = cs.len();
    let mut out: Vec<Seg> = Vec::new();
    let mut plain = String::new();
    let mut i = 0usize;
    let flush_plain = |out: &mut Vec<Seg>, plain: &mut String| {
        if !plain.is_empty() {
            out.push((Style::default(), std::mem::take(plain)));
        }
    };
    while i < n {
        let c = cs[i];
        // string
        if c == '"' || c == '\'' {
            let quote = c;
            let mut j = i + 1;
            while j < n && cs[j] != quote {
                if cs[j] == '\\' && j + 1 < n { j += 2; continue; }
                if cs[j] == '\n' { break; } // shouldn't occur inside a line
                j += 1;
            }
            let end = (j + 1).min(n);
            flush_plain(&mut out, &mut plain);
            out.push((style(Role::SyntaxString, Modifier::empty()), seg(&cs, i, end)));
            i = end;
            continue;
        }
        // line comment
        for prefix in line_comment_prefixes(lang) {
            if line[i..].starts_with(prefix) {
                flush_plain(&mut out, &mut plain);
                out.push((style(Role::SyntaxComment, Modifier::DIM), line[i..].to_string()));
                return out;
            }
        }
        // number
        if c.is_ascii_digit() || (c == '.' && i + 1 < n && cs[i+1].is_ascii_digit()) {
            let mut j = i;
            while j < n {
                if cs[j].is_ascii_digit() { j += 1; continue; }
                match cs[j] {
                    '.' | 'x' | 'o' | 'b' | '_' | 'e' | 'E' => { j += 1; }
                    'f' | 'i' | 'u' | 'l' | 'z' => {
                        // type suffix: only if preceded by a digit
                        ...
                    }
                    _ => break,
                }
            }
            ...
        }
        // keyword (only at a word boundary)
        if c.is_ascii_alphabetic() || c == '_' {
            let mut j = i;
            while j < n && (cs[j].is_ascii_alphanumeric() || cs[j] == '_') {
                j += 1;
            }
            let word: String = seg(&cs, i, j);
            if lang_keywords(lang).contains(&word.as_str()) {
                flush_plain(&mut out, &mut plain);
                out.push((style(Role::SyntaxKeyword, Modifier::empty()), word));
                i = j;
                continue;
            }
        }
        plain.push(c);
        i += 1;
    }
    flush_plain(&mut out, &mut plain);
    out
}
```

