// ── generic code highlighting for file preview ───────────────────

/// Language detection from a file path.
pub fn language_from_path(path: &str) -> Option<&'static str> {
    let ext = std::path::Path::new(path)
        .extension()
        .and_then(|e| e.to_str())?
        .to_ascii_lowercase();

    // Also check the file name itself for special cases
    let file_name = std::path::Path::new(path)
        .file_name()
        .and_then(|f| f.to_str())
        .unwrap_or("");
    let file_name_lc = file_name.to_ascii_lowercase();

    if file_name_lc == "dockerfile" || file_name_lc == "makefile" {
        return Some("shell"); // treat as shell-ish
    }

    Some(match ext.as_str() {
        "rs" => "rust",
        "py" => "python",
        "c" | "h" => "c",
        "cpp" | "cc" | "cxx" | "hpp" | "hh" => "cpp",
        "go" => "go",
        "java" | "kt" | "kts" | "scala" => "java",
        "js" | "mjs" | "cjs" => "javascript",
        "ts" | "tsx" => "typescript",
        "sh" | "bash" | "zsh" | "ksh" | "fish" | "mk" | "make" => "shell",
        "json" => "json",
        "md" | "markdown" | "mdx" => "markdown",
        "yaml" | "yml" | "toml" | "ini" | "cfg" | "conf" | "env" => "config",
        "html" | "htm" | "xml" => "html",
        "css" | "scss" | "sass" => "css",
        "sql" => "sql",
        "lua" => "lua",
        "rb" | "rake" => "ruby",
        "swift" => "swift",
        "Dockerfile" => "shell",
        _ => "generic",
    })
}
