        }
    }

    fn tokenize(&mut self, line: &str, lang: &str, palette: &Palette) -> Vec<Seg> {
        let style = |role: Role, mods: Modifier| palette.style(role, mods);
        let cs: Vec<char> = line.chars().collect();
        let n = cs.len();
        let mut out: Vec<Seg> = Vec::new();
        let mut plain = String::new();
        let mut i = 0usize;

        let keywords = keywords_for(lang);
        let line_comment = line_comment_prefix(lang);
        let has_block_comment = has_block_comment_prefix(lang);

        while i < n {
            let c = cs[i];

            // String literals
            if c == '"' || c == '\'' {
                let quote = c;
                let mut j = i + 1;
                while j < n {
                    if cs[j] == '\\' { j += 2; continue; }
                    if cs[j] == quote { j += 1; break; }
                    j += 1;
                }
                if !plain.is_empty() {
                    out.push((Style::default(), std::mem::take(&mut plain)));
                }
                out.push((style(Role::SyntaxString, Modifier::empty()), seg(&cs, i, j)));
                i = j;
                continue;
            }

            // Line comment
            if line_comment.is_some_and(|p| line[i..].starts_with(p)) {
                if !plain.is_empty() {
                    out.push((Style::default(), std::mem::take(&mut plain)));
                }
                out.push((style(Role::SyntaxComment, Modifier::DIM), line[i..].to_string()));
                return out;
            }

            // Block comment start
            if has_block_comment && line[i..].starts_with("/*") {
                if !plain.is_empty() {
                    out.push((Style::default(), std::mem::take(&mut plain)));
                }
                // Check if the block comment closes on this line
                let rest = &line[i + 2..];
                if let Some(close_pos) = rest.find("*/") {
                    let end = i + 2 + close_pos + 2;
                    out.push((style(Role::SyntaxComment, Modifier::DIM), seg(&cs, i, end)));
                    i = end;
                } else {
                    out.push((style(Role::SyntaxComment, Modifier::DIM), line[i..].to_string()));
                    self.block_comment = true;
                    return out;
                }
                continue;
            }

            // Numbers
            if c.is_ascii_digit() {
                let mut j = i + 1;
                while j < n && (cs[j].is_ascii_digit() || matches!(cs[j], '.' | 'x' | 'X' | 'o' | 'O' | 'b' | 'B' | '_' | 'e' | 'E')) {
                    j += 1;
                }
                if !plain.is_empty() {
                    out.push((Style::default(), std::mem::take(&mut plain)));
                }
                out.push((style(Role::SyntaxNumber, Modifier::empty()), seg(&cs, i, j)));
                i = j;
                continue;
            }

            // Keywords
            if c.is_ascii_alphabetic() || c == '_' {
                let mut j = i + 1;
                while j < n && (cs[j].is_ascii_alphanumeric() || cs[j] == '_') {
                    j += 1;
                }
                let word = &line[i..j];
                if keywords.contains(&word) {
                    if !plain.is_empty() {
                        out.push((Style::default(), std::mem::take(&mut plain)));
                    }
                    out.push((style(Role::SyntaxKeyword, Modifier::empty()), word.to_string()));
                    i = j;
                    continue;
                }
            }

            plain.push(c);
            i += 1;
        }
        if !plain.is_empty() {
            out.push((Style::default(), plain));
        }
        out
    }
