/// A stateful per-line code highlighter for the picker preview pane
/// (docs/tui-file-picker.md section 9: "code highlight is a later
/// add"). Carries block-comment and markdown-fence state across
/// lines. For JSON files it delegates to [`json_line_p`]; for
/// markdown files to [`md_line`]; for all other languages it uses
/// a basic tokenizer for strings, comments, numbers, and a small
/// keyword set.
pub struct CodeHighlighter {
    in_block_comment: bool,
    md_fence: bool,
}

impl CodeHighlighter {
    pub fn new() -> Self {
        Self {
            in_block_comment: false,
            md_fence: false,
        }
    }

    /// Highlight one line of code. `lang` is from [`language_from_path`].
    pub fn line(&mut self, line: &str, lang: &str, palette: &Palette) -> Vec<Seg> {
        match lang {
            "json" => json_line_p(line, palette),
            "markdown" => md_line(line, &mut self.md_fence, palette),
            _ => self.code_line(line, lang, palette),
        }
    }

    fn code_line(&mut self, line: &str, lang: &str, palette: &Palette) -> Vec<Seg> {
        let style = |role: Role, mods: Modifier| palette.style(role, mods);
        let cs: Vec<char> = line.chars().collect();
        let n = cs.len();
        let mut out: Vec<Seg> = Vec::new();
        let mut plain = String::new();
        let mut i = 0usize;

        let kws = keywords_for(lang);
        let lc_prefixes = line_comment_prefixes(lang);
        let has_block = has_block_comment(lang);

        // Resume a block comment from the previous line.
        if self.in_block_comment {
            if let Some(close_pos) = line.find("*/") {
                let end = close_pos + 2;
                self.in_block_comment = false;
                out.push((style(Role::SyntaxComment, Modifier::DIM), line[..end].to_string()));
                i = end;
            } else {
                return vec![(style(Role::SyntaxComment, Modifier::DIM), line.to_string())];
            }
        }

        while i < n {
            let c = cs[i];

            // String literal
            if c == '"' || c == '\'' {
                let quote = c;
                let mut j = i + 1;
                while j < n {
                    if cs[j] == '\\' && j + 1 < n {
                        j += 2;
                        continue;
                    }
                    if cs[j] == quote {
                        j += 1;
                        break;
                    }
                    j += 1;
                }
                if !plain.is_empty() {
                    out.push((Style::default(), std::mem::take(&mut plain)));
                }
                out.push((
                    style(Role::SyntaxString, Modifier::empty()),
                    seg(&cs, i, j),
                ));
                i = j;
                continue;
            }

            // Line comment
            if lc_prefixes.iter().any(|p| line[i..].starts_with(p)) {
                if !plain.is_empty() {
                    out.push((Style::default(), std::mem::take(&mut plain)));
                }
                out.push((
                    style(Role::SyntaxComment, Modifier::DIM),
                    line[i..].to_string(),
                ));
                return out;
            }

            // Block comment
            if has_block && line[i..].starts_with("/*") {
                if !plain.is_empty() {
                    out.push((Style::default(), std::mem::take(&mut plain)));
                }
                let rest = &line[i + 2..];
                if let Some(close_pos) = rest.find("*/") {
                    let end = i + 2 + close_pos + 2;
                    out.push((
                        style(Role::SyntaxComment, Modifier::DIM),
                        seg(&cs, i, end),
                    ));
                    i = end;
                } else {
                    out.push((
                        style(Role::SyntaxComment, Modifier::DIM),
                        line[i..].to_string(),
                    ));
                    self.in_block_comment = true;
                    return out;
                }
                continue;
            }

            // Number
            if c.is_ascii_digit() {
                let mut j = i + 1;
                while j < n
                    && (cs[j].is_ascii_digit()
                        || matches!(cs[j], '.' | 'x' | 'X' | 'o' | 'O' | 'b' | 'B' | 'e' | 'E' | '_'))
                {
                    j += 1;
                }
                if !plain.is_empty() {
                    out.push((Style::default(), std::mem::take(&mut plain)));
                }
                out.push((
                    style(Role::SyntaxNumber, Modifier::empty()),
                    seg(&cs, i, j),
                ));
                i = j;
                continue;
            }

            // Keyword / identifier
            if c.is_ascii_alphabetic() || c == '_' {
                let mut j = i + 1;
                while j < n && (cs[j].is_ascii_alphanumeric() || cs[j] == '_') {
                    j += 1;
                }
                let word = &line[i..j];
                if kws.contains(&word) {
                    if !plain.is_empty() {
                        out.push((Style::default(), std::mem::take(&mut plain)));
                    }
                    out.push((style(Role::SyntaxKeyword, Modifier::empty()), word.to_string()));
                    i = j;
                    continue;
                }
            }

            plain.push(c);
            i += 1;
        }
        if !plain.is_empty() {
            out.push((Style::default(), plain));
        }
        out
    }
}

impl Default for CodeHighlighter {
    fn default() -> Self {
