                        style(Role::SyntaxComment, Modifier::DIM),
                        seg(&cs, i, end),
                    ));
                    i = end;
                } else {
                    out.push((
                        style(Role::SyntaxComment, Modifier::DIM),
                        line[i..].to_string(),
                    ));
                    self.in_block_comment = true;
                    return out;
                }
                continue;
            }

            // Number literal.
            if c.is_ascii_digit() {
                let mut j = i + 1;
                while j < n
                    && (cs[j].is_ascii_digit()
                        || matches!(cs[j], '.' | 'x' | 'X' | 'o' | 'O' | 'b' | 'B' | 'e' | 'E' | '_' | 'f' | 'F' | 'a' | 'A' | 'c' | 'C' | 'd' | 'D'))
                {
                    j += 1;
                }
                flush_plain(&mut out, &mut plain);
                out.push((
                    style(Role::SyntaxNumber, Modifier::empty()),
                    seg(&cs, i, j),
                ));
                i = j;
                continue;
            }

            // Identifier / keyword.
            if c.is_ascii_alphabetic() || c == '_' {
                let mut j = i + 1;
                while j < n && (cs[j].is_ascii_alphanumeric() || cs[j] == '_') {
                    j += 1;
                }
                let word = &line[i..j];
                if kws.contains(&word) {
                    flush_plain(&mut out, &mut plain);
                    out.push((
                        style(Role::SyntaxKeyword, Modifier::empty()),
                        word.to_string(),
                    ));
                    i = j;
                    continue;
                }
            }

            plain.push(c);
            i += 1;
        }
        flush_plain(&mut out, &mut plain);
        out
    }
}

