            rows.push(vec![(*hint, format!("↳ {count} lines hidden"))]);
        }
        BodyPlan::SummaryLine => {
            let n = if count == 1 { "1 line" } else { "lines" };
            rows.push(vec![(*hint, format!("↳ {count} {n}"))]);
        }
        BodyPlan::Lines => {
            let cap = if expanded {
