/// The read tool prefixes every content line with its 1-based file
/// line number (`"123: "`). Split that prefix off so the highlighter
/// only sees the file content. Lines without a digit-colon prefix
/// (annotation lines like "(5 lines omitted)") come back unsplit.
fn split_line_number(line: &str) -> (Option<&str>, &str) {
    match line.find(':') {
        Some(pos) if pos > 0 && line[..pos].bytes().all(|b| b.is_ascii_digit()) => {
            let rest = line[pos + 1..].strip_prefix(' ').unwrap_or(&line[pos + 1..]);
            (Some(&line[..pos]), rest)
        }
        _ => (None, line),
    }
}
```

