/// Split a read body line into its `N: ` line-number prefix and the
/// file content. The read tool prefixes every output line with its
/// 1-based file line number (`{n}: `). Annotation lines (`(N lines
/// omitted)`, `(End of file ...)`) have no prefix. The first `:` in
/// the line is the separator: everything before it is the line number.
fn split_line_number(line: &str) -> (Option<&str>, &str) {
    match line.find(':') {
        Some(pos) if pos > 0 && line[..pos].bytes().all(|b| b.is_ascii_digit()) => {
            let rest = &line[pos + 1..];
            let rest = rest.strip_prefix(' ').unwrap_or(rest);
            (Some(&line[..pos]), rest)
        }
        _ => (None, line),
    }
}
```

