/// Commit the picker.
///
/// When a file is selected, the `@query` token is replaced with
/// `@<value>` so the model receives an unambiguous file-reference
/// marker. When there are zero results, the `@` is stripped and
/// the query text stays as plain text so the picker does not
/// auto-reopen on the next keystroke. The caller already closed
/// the state; this drops the matcher. The caret stays at the
/// replacement end.
fn commit_picker(&mut self, sel: Option<usize>) {
    match sel {
        Some(idx) => {
            if let Some(m) = &self.picker_matcher {
                let snap = m.snapshot();
                if let Some(item) = snap.items.get(idx) {
                    if let Some((at_col, _)) = self.editor().at_token_info() {
                        self.editor().replace_at_token(at_col, &format!("@{}", item.value));
                    }
                }
            }
        }
        None => {
            // Zero results: strip the `@` so the token stops
            // auto-triggering the picker. The query text stays as
            // plain text in the draft.
            if let Some((at_col, query)) = self.editor().at_token_info() {
                self.editor().replace_at_token(at_col, &query);
            }
        }
    }
    self.picker_matcher = None;
}

