fn sync_picker(&mut self) {
    let token = self.editor().at_token_info().map(|(col, q)| (col, q));
    match token {
        Some((at_col, _)) if !self.picker.open => {
            // Only auto-open if this @ was not already dismissed/committed
            if self.picker_dismissed_at_col != Some(at_col) {
                self.open_picker();
